   151→impl std::fmt::Display for StravaErrorResponse {
   152→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
   153→        if self.errors.is_empty() {
   154→            write!(f, "{}", self.message)
   155→        } else {
   156→            let details: Vec<String> = self
   157→                .errors
   158→                .iter()
   159→                .map(|e| format!("{}: {}", e.field, e.code))
   160→                .collect();
   161→            write!(f, "{} ({})", self.message, details.join(", "))
   162→        }
   163→    }
   164→}
