   322→impl OAuthHandler for DefaultOAuthHandler {
   323→    async fn start_authorization(
   324→        &self,
   325→        platform: SyncPlatform,
   326→    ) -> Result<AuthorizationUrl, SyncError> {
   327→        if !platform.uses_oauth() {
   328→            return Err(SyncError::NotConfigured(platform));
   329→        }
   330→
   331→        let configs = self.configs.read().await;
   332→        let config = configs
   333→            .get(&platform)
   334→            .ok_or(SyncError::NotConfigured(platform))?;
   335→
   336→        let state = Self::generate_state();
   337→
   338→        // Store pending state
   339→        self.pending_states
   340→            .write()
   341→            .await
   342→            .insert(state.clone(), platform);
   343→
   344→        let url = Self::build_auth_url(config, platform, &state);
   345→
   346→        tracing::info!("Starting OAuth flow for {:?}", platform);
   347→
   348→        Ok(AuthorizationUrl { url, state })
   349→    }
   350→
   351→    async fn handle_callback(&self, code: &str, state: &str) -> Result<TokenResponse, SyncError> {
   352→        // Verify state
   353→        let pending = self.pending_states.write().await.remove(state);
   354→        let platform = pending.ok_or(SyncError::AuthorizationRequired)?;
   355→
   356→        let configs = self.configs.read().await;
   357→        let config = configs
   358→            .get(&platform)
   359→            .ok_or(SyncError::NotConfigured(platform))?;
   360→
   361→        tracing::info!("Handling OAuth callback for {:?}", platform);
   362→
   363→        // Exchange authorization code for tokens
   364→        let tokens = match platform {
   365→            SyncPlatform::Strava => {
   366→                self.exchange_strava_token(code, config).await?
   367→            }
   368→            _ => {
   369→                // For other platforms, return an error until implemented
   370→                return Err(SyncError::NotConfigured(platform));
   371→            }
   372→        };
   373→
   374→        // Store tokens
   375→        self.tokens.write().await.insert(platform, tokens.clone());
   376→
   377→        Ok(tokens)
   378→    }
