   380→    /// Exchange authorization code for tokens with Strava's OAuth endpoint
   381→    async fn exchange_strava_token(
   382→        &self,
   383→        code: &str,
   384→        config: &OAuthConfig,
   385→    ) -> Result<TokenResponse, SyncError> {
   386→        let client_secret = config
   387→            .client_secret
   388→            .as_ref()
   389→            .ok_or_else(|| SyncError::NotConfigured(SyncPlatform::Strava))?;
   390→
   391→        // Build the token request
   392→        let params = [
   393→            ("client_id", config.client_id.as_str()),
   394→            ("client_secret", client_secret.as_str()),
   395→            ("code", code),
   396→            ("grant_type", "authorization_code"),
   397→        ];
   398→
   399→        tracing::debug!("Exchanging authorization code with Strava token endpoint");
   400→
   401→        let response = self
   402→            .http_client
   403→            .post(&self.strava_token_url)
   404→            .form(&params)
   405→            .send()
   406→            .await
   407→            .map_err(|e| SyncError::NetworkError(format!("Failed to send token request: {}", e)))?;
   408→
   409→        let status = response.status();
   410→        let body = response
   411→            .text()
   412→            .await
   413→            .map_err(|e| SyncError::NetworkError(format!("Failed to read response body: {}", e)))?;
   414→
   415→        if !status.is_success() {
   416→            // Try to parse as Strava error response
   417→            if let Ok(error_response) = serde_json::from_str::<StravaErrorResponse>(&body) {
   418→                tracing::error!("Strava token exchange failed: {}", error_response);
   419→                return Err(SyncError::ApiError(format!(
   420→                    "Strava OAuth error: {}",
   421→                    error_response
   422→                )));
   423→            }
   424→            // Fall back to generic error
   425→            tracing::error!("Strava token exchange failed with status {}: {}", status, body);
   426→            return Err(SyncError::ApiError(format!(
   427→                "Strava OAuth failed with status {}: {}",
   428→                status, body
   429→            )));
   430→        }
   431→
   432→        // Parse successful response
   433→        let strava_response: StravaTokenResponse = serde_json::from_str(&body)
   434→            .map_err(|e| SyncError::ApiError(format!("Failed to parse token response: {}", e)))?;
   435→
   436→        // Convert Unix timestamp to DateTime<Utc>
   437→        let expires_at = Utc
   438→            .timestamp_opt(strava_response.expires_at, 0)
   439→            .single()
   440→            .unwrap_or_else(|| Utc::now() + Duration::hours(1));
   441→
   442→        tracing::info!(
   443→            "Successfully exchanged code for Strava tokens (expires at: {})",
   444→            expires_at
   445→        );
   446→
   447→        Ok(TokenResponse {
   448→            access_token: strava_response.access_token,
   449→            refresh_token: Some(strava_response.refresh_token),
   450→            expires_at,
   451→        })
   452→    }
