/// TrainingPeaks OAuth scopes
pub mod scopes {
    /// Read athlete profile
    pub const ATHLETE_PROFILE: &str = "athlete:profile";
    /// Read workouts
    pub const WORKOUTS_READ: &str = "workouts:read";
    /// Write/upload files (activities)
