   210→    /// Calculate estimated TSS and IF for a given FTP.
   211→    pub fn calculate_estimates(&mut self, ftp: u16) {
   212→        if self.segments.is_empty() || ftp == 0 {
   213→            return;
   214→        }
   215→
   216→        // Calculate weighted average intensity
   217→        let mut total_weighted_power = 0.0f64;
   218→        let mut total_duration = 0u32;
   219→
   220→        for segment in &self.segments {
   221→            let duration = segment.duration_seconds;
   222→            let avg_power = match &segment.power_target {
