   226→                    let start_watts = start.to_watts(ftp) as f64;
   227→                    let end_watts = end.to_watts(ftp) as f64;
   228→                    (start_watts + end_watts) / 2.0
   229→                }
   230→            };
   231→
   232→            total_weighted_power += avg_power * duration as f64;
   233→            total_duration += duration;
   234→        }
   235→
   236→        if total_duration > 0 {
   237→            let avg_power = total_weighted_power / total_duration as f64;
   238→            let intensity_factor = (avg_power / ftp as f64) as f32;
   239→            let duration_hours = total_duration as f32 / 3600.0;
   240→            let tss = duration_hours * intensity_factor * intensity_factor * 100.0;
   241→
   242→            self.estimated_if = Some(intensity_factor);
   243→            self.estimated_tss = Some(tss);
   244→        }
   245→    }
   246→}
