   514→    ///
   515→    /// TrainingPeaks processes uploads asynchronously, so we need to poll for status.
   516→    /// Returns `UploadStatus::Ready` with `file_id` when processing is complete,
   517→    /// `UploadStatus::Error` with a message if processing failed, or
   518→    /// `UploadStatus::Processing` if still being processed.
   519→    ///
   520→    /// # Arguments
   521→    /// * `upload_id` - The upload ID returned from `upload_activity`
   522→    ///
   523→    /// # Returns
   524→    /// The current upload status
   525→    ///
   526→    /// # Errors
   527→    /// * `RateLimited` - If TrainingPeaks' rate limit was exceeded
   528→    /// * `TokenExpired` - If the access token is invalid or expired
   529→    /// * `Timeout` - If the request timed out
   530→    /// * `NetworkError` - If a network error occurred
   531→    pub async fn check_upload_status(&self, upload_id: &str) -> Result<UploadStatus, SyncError> {
   532→        let token = self
