   552→                        "TrainingPeaks status check timed out after {} seconds",
   553→                        DEFAULT_TIMEOUT_SECS
   554→                    );
   555→                    SyncError::Timeout(DEFAULT_TIMEOUT_SECS)
   556→                } else if e.is_connect() {
   557→                    SyncError::NetworkError(format!("Connection failed: {}", e))
   558→                } else {
   559→                    SyncError::NetworkError(format!("Failed to check upload status: {}", e))
   560→                }
   561→            })?;
   562→
   563→        let status_code = response.status();
   564→        let body = response
   565→            .text()
   566→            .await
   567→            .map_err(|e| SyncError::NetworkError(format!("Failed to read response body: {}", e)))?;
   568→
   569→        // Handle rate limiting (429 Too Many Requests)
   570→        if status_code == reqwest::StatusCode::TOO_MANY_REQUESTS {
   571→            tracing::warn!("TrainingPeaks API rate limit exceeded");
