   289→    /// Search workouts by criteria.
   290→    pub fn search(&self, criteria: &SearchCriteria) -> Result<Vec<BuiltInWorkout>, LibraryError> {
   291→        let mut workouts = self.get_all()?;
   292→
   293→        // Filter by category
   294→        if let Some(category) = &criteria.category {
   295→            workouts.retain(|w| &w.category == category);
   296→        }
   297→
   298→        // Filter by energy system
   299→        if let Some(energy_system) = &criteria.energy_system {
   300→            workouts.retain(|w| w.energy_systems.contains(energy_system));
   301→        }
   302→
   303→        // Filter by max duration
   304→        if let Some(max_duration) = criteria.max_duration_minutes {
   305→            workouts.retain(|w| w.duration_minutes <= max_duration);
   306→        }
   307→
   308→        // Filter by difficulty range
   309→        if let Some((min, max)) = criteria.difficulty_range {
   310→            workouts.retain(|w| {
   311→                let (tier_min, tier_max) = w.difficulty_tier.difficulty_range();
   312→                tier_min >= min && tier_max <= max
   313→            });
   314→        }
   315→
   316→        // Filter by goal alignment
   317→        if let Some(goal) = &criteria.goal_type {
   318→            workouts.retain(|w| w.goal_alignment.iter().any(|g| g == goal));
   319→        }
   320→
   321→        Ok(workouts)
   322→    }
