   362→fn parse_workout_row(row: &rusqlite::Row) -> rusqlite::Result<BuiltInWorkout> {
   363→    let id_str: String = row.get(0)?;
   364→    let category_str: String = row.get(3)?;
   365→    let energy_systems_json: String = row.get(4)?;
   366→    let goal_alignment_json: String = row.get(5)?;
   367→    let difficulty_str: String = row.get(6)?;
   368→    let segments_json: String = row.get(9)?;
   369→    let created_at_str: String = row.get(10)?;
   370→
   371→    let category = match category_str.as_str() {
   372→        "Recovery" => WorkoutCategory::Recovery,
   373→        "Endurance" => WorkoutCategory::Endurance,
   374→        "SweetSpot" => WorkoutCategory::SweetSpot,
   375→        "Threshold" => WorkoutCategory::Threshold,
   376→        "Vo2max" => WorkoutCategory::Vo2max,
   377→        "Sprint" => WorkoutCategory::Sprint,
   378→        _ => WorkoutCategory::Mixed,
   379→    };
   380→
   381→    let difficulty_tier = match difficulty_str.as_str() {
   382→        "Easy" => DifficultyTier::Easy,
   383→        "Moderate" => DifficultyTier::Moderate,
   384→        "Hard" => DifficultyTier::Hard,
   385→        "VeryHard" => DifficultyTier::VeryHard,
   386→        _ => DifficultyTier::Moderate,
   387→    };
   388→
   389→    Ok(BuiltInWorkout {
   390→        id: Uuid::parse_str(&id_str).unwrap_or_default(),
   391→        title: row.get(1)?,
   392→        description: row.get(2)?,
   393→        category,
   394→        energy_systems: serde_json::from_str(&energy_systems_json).unwrap_or_default(),
   395→        goal_alignment: serde_json::from_str(&goal_alignment_json).unwrap_or_default(),
   396→        difficulty_tier,
   397→        duration_minutes: row.get(7)?,
   398→        base_tss: row.get(8)?,
   399→        segments: serde_json::from_str(&segments_json).unwrap_or_default(),
   400→        created_at: DateTime::parse_from_rfc3339(&created_at_str)
   401→            .map(|t| t.with_timezone(&Utc))
   402→            .unwrap_or_else(|_| Utc::now()),
   403→    })
   404→}
