  1503→/// Parse a power zone from a string like "Zone 3", "Z3", "3", etc.
  1504→fn parse_power_zone(s: &str) -> Option<u8> {
  1505→    let s = s.trim().to_lowercase();
  1506→
  1507→    // Try "zone N" or "zone N" patterns
  1508→    if let Some(rest) = s.strip_prefix("zone") {
  1509→        if let Ok(zone) = rest.trim().parse::<u8>() {
  1510→            if (1..=7).contains(&zone) {
  1511→                return Some(zone);
  1512→            }
  1513→        }
  1514→    }
  1515→
  1516→    // Try "zN" pattern
  1517→    if let Some(rest) = s.strip_prefix('z') {
  1518→        if let Ok(zone) = rest.trim().parse::<u8>() {
  1519→            if (1..=7).contains(&zone) {
  1520→                return Some(zone);
  1521→            }
  1522→        }
  1523→    }
  1524→
  1525→    // Try just a number
  1526→    if let Ok(zone) = s.parse::<u8>() {
  1527→        if (1..=7).contains(&zone) {
  1528→            return Some(zone);
  1529→        }
  1530→    }
  1531→
  1532→    None
  1533→}
